// ======================================================
// User Manual PDF
// ======================================================
//
// A short, static navigation guide to the site — separate from the
// data-driven "Print Summary PDF" (pdfExport.js). This one needs no
// live data at all: it's fixed text plus placeholder image boxes,
// which the site owner will replace with real screenshots later.
// Deliberately kept much shorter than the Summary PDF — one overview
// image per major section of the site, with individual sub-features
// described briefly in text rather than each getting its own
// screenshot (e.g. Curtailment's Daily/Monthly/Yearly/Total views are
// one line each, not four separate images).
//
// Uses the same jsPDF library already loaded for pdfExport.js — no
// new dependency.
//
// Wrapped in an IIFE with a load-guard, matching this codebase's other
// scripts.

(function () {

    if (window.__userManualLoaded) {
        console.log("userManual.js already loaded — skipping re-init (likely a live-reload re-inject).");
        return;
    }
    window.__userManualLoaded = true;


    // ==========================================
    // Layout constants (A4, mm) — same as pdfExport.js
    // ==========================================
    const PAGE_W = 210;
    const PAGE_H = 297;
    const MARGIN = 15;
    const CONTENT_W = PAGE_W - MARGIN * 2;


    // ==========================================
    // Embedded screenshots
    // ==========================================
    // Real screenshots the site owner provided, replacing the dashed
    // placeholder boxes that used to sit in these spots. Only three of
    // the site's placeholders have real images so far -- the rest
    // still use addImagePlaceholder() until more are provided.
    const MAIN_HUB_IMAGE = "data:image/png;base64,";

    const REGION_SIDEBAR_IMAGE = "data:image/png;base64,";

    const HYDROGEN_LEGEND_IMAGE = ""


    // ==========================================
    // Layout helpers
    // ==========================================
    function addPageHeader(doc, title) {
        doc.setFont("helvetica", "normal");
        doc.setFontSize(9);
        doc.setTextColor(150);
        doc.text(title, MARGIN, 10);
        doc.setTextColor(0);
    }

    function addSectionTitle(doc, text, y) {
        doc.setFont("times", "bold");
        doc.setFontSize(16);
        doc.text(text, MARGIN, y);
        doc.setFont("helvetica", "normal");
        return y + 8;
    }

    function addSubheading(doc, text, y) {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(11);
        doc.setTextColor(20);
        doc.text(text, MARGIN, y);
        doc.setFont("helvetica", "normal");
        doc.setTextColor(0);
        return y + 6;
    }

    function addBodyText(doc, text, y, maxWidth) {
        doc.setFontSize(10);
        doc.setTextColor(50);
        const lines = doc.splitTextToSize(text, maxWidth || CONTENT_W);
        doc.text(lines, MARGIN, y);
        doc.setTextColor(0);
        return y + lines.length * 5 + 4;
    }

    // Dashed placeholder box standing in for a real screenshot, to be
    // added later. Labelled clearly so it's obvious what image belongs
    // there once real screenshots are taken.
    function addImagePlaceholder(doc, y, height, label) {
        const x = MARGIN;
        const w = CONTENT_W;
        doc.setDrawColor(180);
        doc.setLineDashPattern([3, 2], 0);
        doc.setFillColor(248, 249, 251);
        doc.roundedRect(x, y, w, height, 2, 2, "FD");
        doc.setLineDashPattern([], 0);

        doc.setFont("helvetica", "italic");
        doc.setFontSize(10);
        doc.setTextColor(140);
        doc.text(`[Screenshot: ${label}]`, x + w / 2, y + height / 2, { align: "center" });
        doc.setFont("helvetica", "normal");
        doc.setTextColor(0);

        return y + height + 8;
    }

    // Same aspect-ratio-preserving fit already proven for the region
    // photos in pdfExport.js — fits within CONTENT_W x maxHeight
    // without stretching, and centers within that box either way
    // (rather than always filling max width), so a tall, narrow
    // screenshot like the region sidebar doesn't get awkwardly
    // stretched sideways to fill the same box width as a wide map
    // screenshot.
    function addFittedImage(doc, y, maxHeight, dataUrl) {
        try {
            const props = doc.getImageProperties(dataUrl);
            const aspectRatio = props.width / props.height;
            let w = CONTENT_W;
            let h = w / aspectRatio;
            if (h > maxHeight) {
                h = maxHeight;
                w = h * aspectRatio;
            }
            const x = MARGIN + (CONTENT_W - w) / 2;
            doc.addImage(dataUrl, "PNG", x, y, w, h);
            return y + h + 8;
        } catch (err) {
            console.log("User manual: failed to place an embedded image.", err);
            return addImagePlaceholder(doc, y, maxHeight, "Image failed to load");
        }
    }

    function addBullet(doc, label, description, y) {
        doc.setFontSize(10);
        doc.setFont("helvetica", "bold");
        doc.setTextColor(20);
        doc.text("\u2022", MARGIN, y);
        doc.text(label, MARGIN + 5, y);
        const labelWidth = doc.getTextWidth(label + "  ");
        doc.setFont("helvetica", "normal");
        doc.setTextColor(60);
        const lines = doc.splitTextToSize(description, CONTENT_W - 5 - labelWidth);
        // First line continues on the same row as the label if it
        // fits; simplest reliable approach is putting the description
        // on the next line when it's more than a few words, which
        // avoids overlap risk without needing exact width measurement.
        doc.text(lines, MARGIN + 5, y + 5);
        doc.setTextColor(0);
        return y + 5 + lines.length * 5 + 3;
    }


    // ==========================================
    // Cover page
    // ==========================================
    function buildCoverPage(doc) {
        doc.setFont("times", "bold");
        doc.setFontSize(26);
        doc.setTextColor(20);
        doc.text("User Manual", MARGIN, 60);

        doc.setDrawColor(24, 144, 255);
        doc.setLineWidth(0.8);
        doc.line(MARGIN, 70, MARGIN + 50, 70);

        doc.setFont("times", "italic");
        doc.setFontSize(13);
        doc.setTextColor(90);
        doc.text("A guide to the UK Wind & Hydrogen Dashboard", MARGIN, 82);

        doc.setFont("helvetica", "normal");
        doc.setFontSize(10);
        doc.setTextColor(120);
        const generatedOn = "27 August 2026";
        doc.text(`Updated ${generatedOn}`, MARGIN, 96);

        doc.setTextColor(60);
        doc.setFontSize(10.5);
        const intro = doc.splitTextToSize(
            "This guide walks through every part of the site — the main map, each region's data sections, the markers you can see and interact with, and how to export data. Screenshots throughout are placeholders, to be replaced with real images.",
            CONTENT_W - 10
        );
        doc.text(intro, MARGIN, 115);
    }


    // ==========================================
    // 1. Main Hub
    // ==========================================
    function buildMainHubPage(doc) {
        addPageHeader(doc, "User Manual");
        let y = addSectionTitle(doc, "1. Main Hub", 24);

        y = addBodyText(doc, "This is what you see when the site first loads — an interactive map of Great Britain, divided into 14 regions. Click any region to zoom in and open its data panel.", y);

        y = addFittedImage(doc, y, 75, MAIN_HUB_IMAGE);

        y = addSubheading(doc, "Around the map", y + 2);
        y = addBullet(doc, "Map Layers panel (top-left)", "Toggle City Labels, Hydrogen Facilities, Wind Turbines, and simulated H2 Production Sites on or off.", y);
        y = addBullet(doc, "Hydrogen Facilities Legend", "Explains what each facility marker's colour and shape mean.", y);
        y = addBullet(doc, "Live GB Grid widget", "A live, national snapshot of what's generating Great Britain's electricity right now.", y);
        y = addBullet(doc, "Collapse arrows (\u00AB)", "Each left-side panel can be tucked away and brought back with the same button.", y);
        y = addBullet(doc, "? button (top-right)", "Opens the About This Site panel — who built it, why, and where the data comes from.", y);
        y = addBullet(doc, "Export buttons (top-right)", "Download this User Manual, or generate the full data Summary PDF covering every region.", y);
    }


    // ==========================================
    // 2. Region Sidebar
    // ==========================================
    function buildRegionSidebarPage(doc) {
        doc.addPage();
        addPageHeader(doc, "User Manual");
        let y = addSectionTitle(doc, "2. Region Sidebar", 24);

        y = addBodyText(doc, "Clicking a region zooms the map in and opens a sidebar with several data sections, called up using the tabs at the top.", y);

        y = addFittedImage(doc, y, 75, REGION_SIDEBAR_IMAGE);

        y = addSubheading(doc, "Sidebar sections", y + 2);
        y = addBullet(doc, "Generation Mix", "Live breakdown of what's generating this region's electricity right now.", y);
        y = addBullet(doc, "Curtailment", "Wind power switched off due to grid limits or technical problems. Daily, Monthly, Yearly, and Total views.", y);
        y = addBullet(doc, "Wind Capacity", "Installed wind capacity over time, plus an estimate of near-term growth.", y);
        y = addBullet(doc, "H2 Demand", "Real UK hydrogen demand by sector, estimated down to regions based on historic demand data from industrial processes. Some sectors weren't estimated as they had no relevant data to base an estimate on.", y);
        y = addBullet(doc, "H2 Production", "A simulation: how much hydrogen could be made from this region's curtailed wind. This simulation is based on previous work, there is more information available in the about section located on the top right about the original work.", y);
    }


    // ==========================================
    // 3. Map Markers
    // ==========================================
    function buildMapMarkersPage(doc) {
        doc.addPage();
        addPageHeader(doc, "User Manual");
        let y = addSectionTitle(doc, "3. Map Markers", 24);

        y = addBodyText(doc, "Several marker types can be switched on from the Map Layers panel. Hover over any marker to see details in a popup.", y);

        y = addFittedImage(doc, y, 70, HYDROGEN_LEGEND_IMAGE);

        y = addSubheading(doc, "Marker types", y + 2);
        y = addBullet(doc, "Wind Turbines", "Real UK wind farms depicted with little blue dots on the map. Hovering shows the farm's name.", y);
        y = addBullet(doc, "Hydrogen Facilities", "Real refineries, chemical plants, and other hydrogen-using sites. Displayed in many colors and operational conditions, types can be seen from the facility legend widget on the left of the main hub.", y);
        y = addBullet(doc, "H2 Production Sites", "Simulated electrolyser hubs, named after the real substation for which the relevant wind clusters for that region connect through. Not real installations, just simulations. Depicted as full purple circles on the map.", y);
        y = addBullet(doc, "City Labels", "Reference points to help orient the map and for the user's convenience. Depicted as full white circles.", y);
    }


    // ==========================================
    // 4. Exporting & Learning More
    // ==========================================
    function buildExportPage(doc) {
        doc.addPage();
        addPageHeader(doc, "User Manual");
        let y = addSectionTitle(doc, "4. Exporting & Learning More", 24);

        y = addSubheading(doc, "Print Summary PDF", y + 2);
        y = addBodyText(doc, "Generates a full data report: a national summary, then every region with its own map, generation mix, curtailment trend, and data tables. Takes a little time to load for the first time if it's your first time coming onto the site because of the sheer data it downloads.", y);

        y = addSubheading(doc, "About This Site", y + 4);
        y = addBodyText(doc, "Opens from the ? button. Covers why the site was built, credits, and exactly where every dataset comes from. Also provides more data on previous research related to the site, has acknowledgements, and a link for donations.", y);

        y = addSubheading(doc, "This User Manual", y + 4);
        y = addBodyText(doc, "This document. Available any time from the button next to Print Summary PDF.", y);
    }


    // ==========================================
    // Main entry point
    // ==========================================
    function generateUserManual() {
        try {
            if (typeof window.jspdf === "undefined") {
                throw new Error("jsPDF not loaded — check index.html script tags.");
            }

            const { jsPDF } = window.jspdf;
            const doc = new jsPDF({ unit: "mm", format: "a4" });

            buildCoverPage(doc);
            doc.addPage();
            buildMainHubPage(doc);
            buildRegionSidebarPage(doc);
            buildMapMarkersPage(doc);
            buildExportPage(doc);

            doc.save("UK_Wind_Hydrogen_Dashboard_User_Manual.pdf");
            console.log("User manual: done.");
        } catch (err) {
            console.error("User manual generation failed:", err);
            alert("Something went wrong generating the user manual. Check the browser console for details.");
        }
    }

    function initButton() {
        const btn = document.getElementById("userManualBtn");
        if (!btn) return;
        btn.addEventListener("click", generateUserManual);
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initButton);
    } else {
        initButton();
    }

})();